insert into tap_results select throws_ok($$insert into public.product_units(id,organization_id,product_id,name,factor) values(pg_temp.i(499),pg_temp.i(1),pg_temp.i(301),'Invalid','NaN')$$,'23514',null,'Database rejects non-finite unit factors even through a missed RPC check');
