insert into tap_results select is(app_private.exact_credit_book('{"clients":[{"outstanding":18014398509481982,"overdue":0}],"aging":{"notDue":18014398509481982},"outstanding":18014398509481982,"overdue":0,"creditSales":18014398509481982,"openingBalances":0,"cashCollected":0}')#>>'{exactTotals,outstanding}','18014398509481982','Account-wide credit totals retain all digits');
insert into tap_results select is(app_private.exact_credit_book('{"clients":[{"outstanding":18014398509481982,"overdue":0}],"aging":{"notDue":18014398509481982},"outstanding":18014398509481982}')#>>'{clients,0,outstandingExact}','18014398509481982','Per-customer totals have an exact representation');
insert into tap_results select is(app_private.exact_credit_book('{"clients":[],"aging":{"notDue":18014398509481982},"outstanding":18014398509481982}')#>>'{agingExact,notDue}','18014398509481982','Aging totals retain exact centavos');
insert into tap_results select is(jsonb_typeof(app_private.exact_credit_book('{"clients":[],"aging":{},"outstanding":18014398509481982}')->'outstanding'),'number','Legacy numeric credit fields remain compatible');
insert into tap_results select is(app_private.exact_dashboard('{"grossSales":18014398509481982,"branchTotals":[{"total":18014398509481982}]}')#>>'{branchTotals,0,exactTotals,total}','18014398509481982','Branch activity totals retain every centavo');
insert into tap_results select is(jsonb_typeof(app_private.exact_dashboard('{"grossSales":18014398509481982}')->'grossSales'),'number','Legacy dashboard fields remain compatible');
insert into tap_results select is(app_private.exact_dashboard('{"expected_cash":18014398509481982}')#>>'{exactTotals,expected_cash}','18014398509481982','Accumulated expected drawer cash keeps an exact representation');
insert into tap_results select throws_ok($$select public.agri_command('price_history',pg_temp.ctx())$$,'42501','Only the owner can read price history','Cashiers cannot access owner price history');
insert into book select public.agri_command('price_history',pg_temp.ctx());
insert into tap_results select is((select data->>'total' from book),'1003','History includes more than the default API 1000-row limit');
insert into tap_results select is((select jsonb_array_length(data->'rows') from book),50,'Each server page is bounded');
insert into tap_results select is(public.agri_command('price_history',pg_temp.ctx()||'{"query":"NEEDLE"}')->>'total','1','Search covers records older than the first 1000');
insert into tap_results select is(public.agri_command('price_history',pg_temp.ctx()||'{"query":"NEEDLE"}')#>>'{rows,0,price}','9007199254740985','Archived history preserves exact large prices');
insert into tap_results select is(public.agri_command('price_history',pg_temp.ctx()||jsonb_build_object('before',(select data->'next' from book)))#>>'{rows,0,version}','952','Tied timestamps page without repeating the preceding version');
insert into tap_results select is(public.agri_command('price_history',pg_temp.ctx()||'{"query":"no matching product"}')->>'total','0','Filtered history does not invent an unfiltered total');
